import {inspectComponent} from './model.mjs';
export function explainStages(c){const groups=[['Pickups',p=>['humbucker','singlecoil','p90'].includes(p.type)],['Volume controls',p=>p.role==='volume'||p.id.endsWith('Volume')],['Tone branch',p=>p.role==='tone'||p.id.endsWith('Tone')||p.type==='capacitor'||p.type==='resistor'||p.type==='network'],['Selector',p=>p.id==='selector'],['Output and ground',p=>p.id==='jack'||p.type==='ground']];if(!['les-paul','sg'].includes(c.state.guitar))groups.splice(1,0,groups.splice(3,1)[0]);return groups.map(([label,predicate])=>{const parts=c.components.filter(predicate);return {label,ids:parts.map(p=>p.id),description:parts.map(p=>{const info=inspectComponent(c,p.id);return info.label+': '+info.terminals.filter(t=>t.connections.length).map(t=>t.label+' → '+t.connections.join(', ')).join('; ');}).join(' · ')};});}
